package net.nuggetmc.tplus.compat.bukkit.block.data;
public class BlockData { protected final net.minecraft.world.level.block.state.BlockState state; public BlockData(){this(null);} public BlockData(net.minecraft.world.level.block.state.BlockState state){this.state=state;} public net.minecraft.world.level.block.state.BlockState nms(){return state;} public SoundGroup getSoundGroup(){return new SoundGroup();} public static final class SoundGroup { public net.nuggetmc.tplus.compat.bukkit.Sound getPlaceSound(){return net.nuggetmc.tplus.compat.bukkit.Sound.BLOCK_STONE_PLACE;} public net.nuggetmc.tplus.compat.bukkit.Sound getBreakSound(){return net.nuggetmc.tplus.compat.bukkit.Sound.BLOCK_STONE_PLACE;} } }
